import * as React from "react";
import {
  PlasmicVideoUpload,
  DefaultVideoUploadProps
} from "./plasmic/sayban/PlasmicVideoUpload";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import { useGlobalActions } from "@plasmicapp/react-web/lib/host";
import {
  MAX_VIDEO_UPLOAD_MB,
  describeVideoRejection,
  uploadedFileBytes
} from "./uploadLimits";

export interface VideoUploadProps extends DefaultVideoUploadProps {}

/**
 * The picked video is base64-encoded into `upload.files[].contents` by the antd
 * Upload wrapper and later shipped inside the JSON body of
 * `POST /panel/staffs/update` — base64 inflates it by ~33% on top of the raw
 * size. Oversized files used to be accepted silently here and then die at the
 * server body limit, while a 0.5s timer in the generated markup flipped the UI
 * to "uploaded" regardless. Rejecting at selection time is the only place the
 * user can still act on it.
 */
function VideoUpload_(props: VideoUploadProps, ref: HTMLElementRefOf<"div">) {
  const { onUploadFilesChange } = props;
  const globalActions = useGlobalActions();

  const handleUploadFilesChange = React.useCallback(
    (files: unknown, ...rest: unknown[]) => {
      const list = Array.isArray(files) ? files : [];
      const rejection = list
        .map(file => describeVideoRejection(file))
        .find(Boolean);

      if (rejection) {
        globalActions?.["Fragment.showToast"]?.(
          "error",
          rejection,
          "top-center",
          5000
        );
        // Clear the selection so the stale oversized file cannot be submitted.
        (onUploadFilesChange as ((value: unknown) => void) | undefined)?.([]);
        return;
      }

      (
        onUploadFilesChange as
          | ((value: unknown, ...args: unknown[]) => void)
          | undefined
      )?.(files, ...rest);
    },
    [globalActions, onUploadFilesChange]
  );

  return (
    <PlasmicVideoUpload
      root={{ ref }}
      {...props}
      onUploadFilesChange={handleUploadFilesChange as never}
    />
  );
}

export { MAX_VIDEO_UPLOAD_MB, uploadedFileBytes };

const VideoUpload = React.forwardRef(VideoUpload_);
export default VideoUpload;
